import{_ as e,c as a,o as n,a6 as o}from"./chunks/framework.CZHnDj0c.js";const x=JSON.parse('{"title":"免费证书HTTPS申请与Nginx配置——完整问答记录","description":"","frontmatter":{},"headers":[],"relativePath":"src/net/https.md","filePath":"src/net/https.md"}'),t={name:"src/net/https.md"},s=o('<h1 id="免费证书https申请与nginx配置——完整问答记录" tabindex="-1">免费证书HTTPS申请与Nginx配置——完整问答记录 <a class="header-anchor" href="#免费证书https申请与nginx配置——完整问答记录" aria-label="Permalink to &quot;免费证书HTTPS申请与Nginx配置——完整问答记录&quot;">​</a></h1><hr><h2 id="_1-用户-我现在服务器上已经有了docker-还有了https整数-然后nginx-怎么才能开启https" tabindex="-1">1. 用户：我现在服务器上已经有了docker,还有了https整数，然后nginx，怎么才能开启https <a class="header-anchor" href="#_1-用户-我现在服务器上已经有了docker-还有了https整数-然后nginx-怎么才能开启https" aria-label="Permalink to &quot;1. 用户：我现在服务器上已经有了docker,还有了https整数，然后nginx，怎么才能开启https&quot;">​</a></h2><p><strong>AI：</strong> 你已经有了 Docker、HTTPS 证书（SSL 证书），还有 Nginx。要开启 HTTPS，通常只需要在 Nginx 配置中正确设置 SSL 相关内容即可。下面是详细步骤：</p><ol><li>准备 SSL 证书文件（.crt 和 .key）</li><li>修改 Nginx 配置，添加 listen 443 ssl 和 ssl_certificate、ssl_certificate_key 路径</li><li>（可选）HTTP 自动跳转到 HTTPS</li><li>检查配置并重载 Nginx</li><li>Docker 场景下注意挂载证书和配置文件</li></ol><p>详细配置和命令见原问答。</p><hr><h2 id="_2-用户-这个路径下已经有这几个文件了-接下来该怎么启动nginx" tabindex="-1">2. 用户：这个路径下已经有这几个文件了：接下来该怎么启动nginx <a class="header-anchor" href="#_2-用户-这个路径下已经有这几个文件了-接下来该怎么启动nginx" aria-label="Permalink to &quot;2. 用户：这个路径下已经有这几个文件了：接下来该怎么启动nginx&quot;">​</a></h2><p><strong>AI：</strong> 你已经有了 Nginx 的配置文件，只需启动 Nginx 服务即可。</p><ul><li>检查配置：<code>nginx -t</code> 或 <code>docker exec -it &lt;nginx容器名&gt; nginx -t</code></li><li>启动/重载 Nginx： <ul><li>宿主机：<code>systemctl start nginx</code> 或 <code>systemctl reload nginx</code></li><li>Docker：<code>docker run ...</code> 或 <code>docker exec &lt;nginx容器名&gt; nginx -s reload</code></li></ul></li><li>访问 <a href="https://xn--6qqv7i2xdt95b" target="_blank" rel="noreferrer">https://你的域名</a> 测试</li></ul><hr><h2 id="_3-用户-systemctl-start-nginx-报错-unit-not-found-我怎么知道我的配置路径在哪-docker-run" tabindex="-1">3. 用户：systemctl start nginx 报错 Unit not found，我怎么知道我的配置路径在哪：docker run ... <a class="header-anchor" href="#_3-用户-systemctl-start-nginx-报错-unit-not-found-我怎么知道我的配置路径在哪-docker-run" aria-label="Permalink to &quot;3. 用户：systemctl start nginx 报错 Unit not found，我怎么知道我的配置路径在哪：docker run ...&quot;">​</a></h2><p><strong>AI：</strong> 报错说明 Nginx 不是以系统服务方式安装的，可能用 Docker。你的配置文件路径就是你本地实际存放配置文件的路径，比如 <code>/root/docker/nginx/</code>。</p><ul><li>用 <code>ls</code> 或 <code>find</code> 命令确认配置和证书路径</li><li>Docker 启动时挂载本地配置和证书到容器内默认路径</li></ul><hr><h2 id="_4-用户-ls-docker-nginx-nginx-conf-才对。而且我不知道我的整数在哪" tabindex="-1">4. 用户：ls /docker/nginx/nginx.conf 才对。而且我不知道我的整数在哪 <a class="header-anchor" href="#_4-用户-ls-docker-nginx-nginx-conf-才对。而且我不知道我的整数在哪" aria-label="Permalink to &quot;4. 用户：ls /docker/nginx/nginx.conf 才对。而且我不知道我的整数在哪&quot;">​</a></h2><p><strong>AI：</strong> 你说的“整数”应该是“证书”。用 <code>find /docker/nginx/ -name &quot;*.crt&quot;</code>、<code>find /docker/nginx/ -name &quot;*.key&quot;</code> 查找证书文件。如果没有，说明还没上传或生成证书。</p><hr><h2 id="_5-用户-find-name-crt-没有返回" tabindex="-1">5. 用户：find -name &quot;*.crt&quot; 没有返回 <a class="header-anchor" href="#_5-用户-find-name-crt-没有返回" aria-label="Permalink to &quot;5. 用户：find  -name &quot;*.crt&quot; 没有返回&quot;">​</a></h2><p><strong>AI：</strong> 没有找到证书文件，说明你还没有上传或生成 SSL 证书。可以用 acme.sh 或 certbot 免费申请 Let&#39;s Encrypt 证书。详细申请步骤见原问答。</p><hr><h2 id="_6-用户-我是-要免费的证书-我是-centos-7" tabindex="-1">6. 用户：我是 要免费的证书，我是 centos 7 <a class="header-anchor" href="#_6-用户-我是-要免费的证书-我是-centos-7" aria-label="Permalink to &quot;6. 用户：我是 要免费的证书，我是 centos 7&quot;">​</a></h2><p><strong>AI：</strong> 推荐用 acme.sh，操作简单。步骤：</p><ol><li>安装 acme.sh</li><li>用 <code>--standalone</code> 模式申请证书</li><li>证书文件在 <code>~/.acme.sh/yourdomain.com/</code></li><li>拷贝证书到 Nginx 目录</li><li>配置 Nginx</li></ol><hr><h2 id="_7-用户-acme-sh-安装很慢-有没有方法配置代理加快" tabindex="-1">7. 用户：acme.sh 安装很慢，有没有方法配置代理加快 <a class="header-anchor" href="#_7-用户-acme-sh-安装很慢-有没有方法配置代理加快" aria-label="Permalink to &quot;7. 用户：acme.sh 安装很慢，有没有方法配置代理加快&quot;">​</a></h2><p><strong>AI：</strong> 可以用 export http_proxy/https_proxy 配置代理，或直接用 acme.sh 的 Gitee 镜像： <code>curl https://gitee.com/neilpang/acme.sh/raw/master/acme.sh | sh</code></p><hr><h2 id="_8-用户-acme-sh-安装后找不到-acme-sh-acme-sh" tabindex="-1">8. 用户：acme.sh 安装后找不到 ~/.acme.sh/acme.sh <a class="header-anchor" href="#_8-用户-acme-sh-安装后找不到-acme-sh-acme-sh" aria-label="Permalink to &quot;8. 用户：acme.sh 安装后找不到 ~/.acme.sh/acme.sh&quot;">​</a></h2><p><strong>AI：</strong> 你只是下载了脚本但没真正安装。正确做法：</p><ol><li>下载脚本 <code>curl ... -o acme.sh</code></li><li><code>chmod +x acme.sh</code></li><li><code>./acme.sh --install</code></li><li>然后 <code>~/.acme.sh/acme.sh</code> 就有了</li></ol><hr><h2 id="_9-用户-acme-sh-issue-报-please-install-socat-tools-first" tabindex="-1">9. 用户：acme.sh --issue 报 Please install socat tools first <a class="header-anchor" href="#_9-用户-acme-sh-issue-报-please-install-socat-tools-first" aria-label="Permalink to &quot;9. 用户：acme.sh --issue 报 Please install socat tools first&quot;">​</a></h2><p><strong>AI：</strong> acme.sh 的 --standalone 模式需要 socat 工具。用 <code>yum install -y socat</code> 安装。</p><hr><h2 id="_10-用户-yum-安装-socat-报-nginx-源-404" tabindex="-1">10. 用户：yum 安装 socat 报 nginx 源 404 <a class="header-anchor" href="#_10-用户-yum-安装-socat-报-nginx-源-404" aria-label="Permalink to &quot;10. 用户：yum 安装 socat 报 nginx 源 404&quot;">​</a></h2><p><strong>AI：</strong> 用 <code>yum --disablerepo=nginx install -y socat</code>，或重新配置 epel 源。socat 在 epel 源，不需要 nginx 源。</p><hr><h2 id="_11-用户-acme-sh-issue-还是提示-please-install-socat-tools-first" tabindex="-1">11. 用户：acme.sh --issue 还是提示 Please install socat tools first <a class="header-anchor" href="#_11-用户-acme-sh-issue-还是提示-please-install-socat-tools-first" aria-label="Permalink to &quot;11. 用户：acme.sh --issue 还是提示 Please install socat tools first&quot;">​</a></h2><p><strong>AI：</strong> 其实 socat 已经安装成功，可以直接申请证书。</p><hr><h2 id="_12-用户-acme-sh-issue-提示-please-update-your-account-with-an-email-address-first" tabindex="-1">12. 用户：acme.sh --issue 提示 Please update your account with an email address first <a class="header-anchor" href="#_12-用户-acme-sh-issue-提示-please-update-your-account-with-an-email-address-first" aria-label="Permalink to &quot;12. 用户：acme.sh --issue 提示 Please update your account with an email address first&quot;">​</a></h2><p><strong>AI：</strong> 需要先注册邮箱： <code>~/.acme.sh/acme.sh --register-account -m 你的邮箱</code> 然后再申请证书。</p><hr><h2 id="_13-用户-证书申请成功-证书路径在哪" tabindex="-1">13. 用户：证书申请成功，证书路径在哪 <a class="header-anchor" href="#_13-用户-证书申请成功-证书路径在哪" aria-label="Permalink to &quot;13. 用户：证书申请成功，证书路径在哪&quot;">​</a></h2><p><strong>AI：</strong> 证书在 <code>/root/.acme.sh/leaiv.cn/</code> 目录下。</p><ul><li>fullchain.cer 证书</li><li>leaiv.cn.key 私钥</li></ul><hr><h2 id="_14-用户-nginx-s-reload-报-invalid-pid-number" tabindex="-1">14. 用户：nginx -s reload 报 invalid PID number <a class="header-anchor" href="#_14-用户-nginx-s-reload-报-invalid-pid-number" aria-label="Permalink to &quot;14. 用户：nginx -s reload 报 invalid PID number&quot;">​</a></h2><p><strong>AI：</strong> 说明 Nginx 没有启动。你可以直接用本机 Nginx 配置和启动 HTTPS，不用 Docker。</p><hr><h2 id="_15-用户-nginx-conf-结构和-server-配置问题" tabindex="-1">15. 用户：nginx.conf 结构和 server 配置问题 <a class="header-anchor" href="#_15-用户-nginx-conf-结构和-server-配置问题" aria-label="Permalink to &quot;15. 用户：nginx.conf 结构和 server 配置问题&quot;">​</a></h2><p><strong>AI：</strong> listen 443 及 ssl 配置只能写在 server 块里，不能直接写在 nginx.conf 的 http 外层。nginx.conf 只负责 include 子配置文件，server 配置写在被 include 的文件里。</p><hr><h2 id="_16-用户-只生成了-leaiv-cn-的证书-web-leaiv-cn-也有效吗-web-nginx-conf-配置对吗" tabindex="-1">16. 用户：只生成了 leaiv.cn 的证书，web.leaiv.cn 也有效吗？_web.nginx.conf 配置对吗？ <a class="header-anchor" href="#_16-用户-只生成了-leaiv-cn-的证书-web-leaiv-cn-也有效吗-web-nginx-conf-配置对吗" aria-label="Permalink to &quot;16. 用户：只生成了 leaiv.cn 的证书，web.leaiv.cn 也有效吗？_web.nginx.conf 配置对吗？&quot;">​</a></h2><p><strong>AI：</strong> 只生成 leaiv.cn 的证书，web.leaiv.cn 用不了。要支持多个域名，申请证书时要把所有域名都写上。</p><hr><h2 id="_17-用户-怎么查证书目录-怎么停掉80端口" tabindex="-1">17. 用户：怎么查证书目录，怎么停掉80端口 <a class="header-anchor" href="#_17-用户-怎么查证书目录-怎么停掉80端口" aria-label="Permalink to &quot;17. 用户：怎么查证书目录，怎么停掉80端口&quot;">​</a></h2><p><strong>AI：</strong> 证书目录：<code>/root/.acme.sh/leaiv.cn/</code> 查 80 端口：<code>lsof -i :80</code> 或 <code>netstat -tlnp | grep :80</code> 停掉进程：<code>kill -9 进程号</code> 或 <code>nginx -s stop</code></p><hr><h2 id="_18-用户-想删除旧证书-申请多个域名证书" tabindex="-1">18. 用户：想删除旧证书，申请多个域名证书 <a class="header-anchor" href="#_18-用户-想删除旧证书-申请多个域名证书" aria-label="Permalink to &quot;18. 用户：想删除旧证书，申请多个域名证书&quot;">​</a></h2><p><strong>AI：</strong> 删除旧证书：<code>rm -rf /root/.acme.sh/leaiv.cn/</code> 申请多个域名： <code>~/.acme.sh/acme.sh --issue -d leaiv.cn -d www.leaiv.cn -d web.leaiv.cn -d company.leaiv.cn -d server.leaiv.cn -d media.leaiv.cn --standalone</code></p><hr><h2 id="_19-用户-以后新增域名还要重新申请吗" tabindex="-1">19. 用户：以后新增域名还要重新申请吗？ <a class="header-anchor" href="#_19-用户-以后新增域名还要重新申请吗" aria-label="Permalink to &quot;19. 用户：以后新增域名还要重新申请吗？&quot;">​</a></h2><p><strong>AI：</strong> 是的，每次新增域名都要把所有需要的域名一起写上重新申请。</p><hr><h2 id="_20-用户-listen-443-及-ssl-配置能不能直接写在-nginx-conf-里-company-nginx-conf-配置对吗" tabindex="-1">20. 用户：listen 443 及 ssl 配置能不能直接写在 nginx.conf 里？_company.nginx.conf 配置对吗？ <a class="header-anchor" href="#_20-用户-listen-443-及-ssl-配置能不能直接写在-nginx-conf-里-company-nginx-conf-配置对吗" aria-label="Permalink to &quot;20. 用户：listen 443 及 ssl 配置能不能直接写在 nginx.conf 里？_company.nginx.conf 配置对吗？&quot;">​</a></h2><p><strong>AI：</strong> 不能，必须写在 server 块里，server 块要在被 include 的文件里。你的 _company.nginx.conf 配置是对的。</p><hr><h2 id="_21-用户-location-50x-html-root-能去掉吗" tabindex="-1">21. 用户：location = /50x.html { root ... } 能去掉吗？ <a class="header-anchor" href="#_21-用户-location-50x-html-root-能去掉吗" aria-label="Permalink to &quot;21. 用户：location = /50x.html { root ... } 能去掉吗？&quot;">​</a></h2><p><strong>AI：</strong> 可以去掉，Nginx 会自动用 server 块的 root 路径查找 50x.html。</p><hr><blockquote><p>本文档为实际操作问答整理，便于后续查阅和复用。</p></blockquote>',73),i=[s];function r(c,l,h,d,g,m){return n(),a("div",null,i)}const p=e(t,[["render",r]]);export{x as __pageData,p as default};
